from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject
from taf.gnb.oam.coam.vdu.schemas.asm.get_rets_diff_v1 import RmodConnector, VduAldBasic, AntennaInfo
from taf.gnb.oam.coam.vdu.schemas.asm.alarms import Alarm
from taf.gnb.oam.coam.vdu.schemas.asm.dist_names import DistNames


class VduMhaState(VduAldBasic):
    mha_type = SchemaField(name='mha_type', optional=True)

    def __init__(self, id, configuration_id, product_code, serial_number, vendor_code, software_version,
                 hardware_version, control_protocol, aisg_protocol_version, release_id3_gpp, control_ports,
                 availability_status, operational_state, procedural_status, alarms, dist_names, mha_type):
        self.id = id
        self.configuration_id = configuration_id
        self.product_code = product_code
        self.serial_number = serial_number
        self.vendor_code = vendor_code
        self.software_version = software_version
        self.hardware_version = hardware_version
        self.control_protocol = control_protocol
        self.aisg_protocol_version = aisg_protocol_version
        self.release_id3_gpp = release_id3_gpp
        self.control_ports = control_ports
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.alarms = alarms
        self.dist_names = dist_names
        self.mha_type = mha_type

        super(VduMhaState, self).__init__(id, configuration_id, product_code, serial_number, vendor_code,
                                          software_version, hardware_version, control_protocol, aisg_protocol_version,
                                          release_id3_gpp, control_ports, availability_status, operational_state,
                                          procedural_status, alarms, dist_names)


class LNAState(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    configuration_id = SchemaField(name='configuration_id', optional=True)
    gain = SchemaField(name='gain', optional=True)
    gain_resolution = SchemaField(name='gain_resolution', optional=True)
    max_supported_gain = SchemaField(name='max_supported_gain', optional=True)
    min_supported_gain = SchemaField(name='min_supported_gain', optional=True)
    mode = SchemaField(name='mode', optional=True)
    amplified_antenna_line = SchemaField(name='amplified_antenna_line', klass=RmodConnector, many=True, optional=True)
    dc_power_sources = SchemaField(name='dc_power_sources', klass=RmodConnector, many=True, not_null=True)
    antenna_info = SchemaField(name='antenna_info', klass=AntennaInfo, optional=True)
    availability_status = SchemaField(name='availability_status', optional=True)
    operational_state = SchemaField(name='operational_state', optional=True)
    procedural_status = SchemaField(name='procedural_status', optional=True)
    alarms = SchemaField(name='alarms', klass=Alarm, not_null=True, many=True)
    dist_names = SchemaField(name='dist_names', not_null=True, klass=DistNames)

    def __init__(self, id, gain, gain_resolution, max_supported_gain, min_supported_gain, mode, alarms, amplified_antenna_line,
                 antenna_info, configuration_id, dist_names, dc_power_sources,
                 availability_status, operational_state, procedural_status):
        self.id = id
        self.alarms = alarms
        self.antenna_info = antenna_info
        self.gain = gain
        self.configuration_id = configuration_id
        self.dist_names = dist_names
        self.gain_resolution = gain_resolution
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.max_supported_gain = max_supported_gain
        self.min_supported_gain = min_supported_gain
        self.mode = mode
        self.amplified_antenna_line = amplified_antenna_line
        self.dc_power_sources = dc_power_sources

        super(LNAState, self).__init__()


class GetMHAsDiffV1(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    ald = SchemaField(name='ald', not_null=True, klass=VduMhaState)
    subunits = SchemaField(name='subunits', not_null=True, klass=LNAState, many=True)

    def __init__(self, id, ald, subunits):
        self.id = id
        self.ald = ald
        self.subunits = subunits

        super(GetMHAsDiffV1, self).__init__()
